
import wfdb
import numpy as np
import matplotlib.pyplot as plt
from scipy.signal import butter, sosfiltfilt
from pathlib import Path

# ============================================================
# 1. PATHS AND SETTINGS
# ============================================================

# ECG and annotations generated by sqrs125_experiment.exe
modified_record_path = (
    r"C:\msys64\tmp\sqrs125_no_minus4\a01"
)

# Original project record: used to obtain Detector 4's detections
project_record_path = str(
    Path(__file__).resolve().parent.parent / "data" / "ao1" / "a01"
)

# Existing Detector 4 matched-pairs file.
# Column 0 contains detected sample positions.
old_pairs_path = (
    Path(__file__).resolve().parent.parent
    / "a01_detector4_matched_pairs.npy"
)

TOLERANCE_MS = 50

# ============================================================
# 2. LOAD ECG RECORDS AND ANNOTATIONS
# ============================================================

modified_record = wfdb.rdrecord(modified_record_path)
ecg = modified_record.p_signal[:, 0].astype(float)
fs = float(modified_record.fs)

# IMPORTANT:
# WFDB returns annotation sample positions on the record's
# sampling grid. Do not convert them from 125 Hz to 100 Hz again.
modified_ann = wfdb.rdann(modified_record_path, "qrs")
# sqrs125 annotations use a 125 Hz time base.
# Convert their sample positions to the ECG's 100 Hz grid.
modified_reference = np.rint(
    modified_ann.sample * fs / 125.0
).astype(int)

# Load the original matched pairs only to retain Detector 4's
# already-computed detections. We discard the old reference
# positions and recompute matching against modified_reference.
old_pairs = np.load(old_pairs_path)
detected = np.sort(np.asarray(old_pairs[:, 0], dtype=int))

# Remove duplicate detections, if any.
detected = np.unique(detected)

# Ensure all sample indices are valid for this ECG.
detected = detected[
    (detected >= 0) & (detected < len(ecg))
]
modified_reference = modified_reference[
    (modified_reference >= 0)
    & (modified_reference < len(ecg))
]

tolerance_samples = int(round(TOLERANCE_MS * fs / 1000))

print("=" * 65)
print("DETECTOR 4 VS SQRS125 WITHOUT THE -4 SAMPLE CORRECTION")
print("=" * 65)
print(f"Sampling frequency: {fs:.1f} Hz")
print(f"ECG samples: {len(ecg)}")
print(f"Detector 4 detections: {len(detected)}")
print(f"Modified reference annotations: {len(modified_reference)}")
print(f"Matching tolerance: {TOLERANCE_MS} ms ({tolerance_samples} samples)")

# ============================================================
# 3. RECOMPUTE MATCHED PAIRS
# ============================================================

# Greedy one-to-one matching:
# each detection and each reference annotation can be used once.
# Among available references within tolerance, choose the nearest.
reference_sorted = np.sort(modified_reference)
used_reference = np.zeros(len(reference_sorted), dtype=bool)

matched_rows = []
false_positive_count = 0

for det in detected:
    left = np.searchsorted(
        reference_sorted, det - tolerance_samples, side="left"
    )
    right = np.searchsorted(
        reference_sorted, det + tolerance_samples, side="right"
    )

    candidates = np.arange(left, right)
    candidates = candidates[~used_reference[candidates]]

    if len(candidates) == 0:
        false_positive_count += 1
        continue

    # Find the nearest available reference annotation.
    distances = np.abs(reference_sorted[candidates] - det)
    best_position = candidates[np.argmin(distances)]
    ref = int(reference_sorted[best_position])

    used_reference[best_position] = True
    matched_rows.append((int(det), ref, int(det - ref)))

matched = np.asarray(matched_rows, dtype=int).reshape(-1, 3)

true_positives = len(matched)
false_negatives = int(np.sum(~used_reference))
false_positives = len(detected) - true_positives

if true_positives == 0:
    raise RuntimeError(
        "No beats matched. Check the annotation time base and record paths."
    )

detected_matched = matched[:, 0]
reference_matched = matched[:, 1]
error_samples = matched[:, 2]
error_ms = error_samples / fs * 1000.0
absolute_error_ms = np.abs(error_ms)

# ============================================================
# 4. PRINT VALIDATION AND TIMING RESULTS
# ============================================================

sensitivity = (
    true_positives / (true_positives + false_negatives) * 100
    if true_positives + false_negatives else 0
)
precision = (
    true_positives / (true_positives + false_positives) * 100
    if true_positives + false_positives else 0
)
f1 = (
    2 * sensitivity * precision / (sensitivity + precision)
    if sensitivity + precision else 0
)

print("\nMATCHING RESULTS")
print("True positives:", true_positives)
print("False positives:", false_positives)
print("False negatives:", false_negatives)
print(f"Sensitivity: {sensitivity:.5f}%")
print(f"Precision:   {precision:.5f}%")
print(f"F1 score:    {f1:.5f}%")

print("\nSIGNED TIMING ERROR")
print(f"Mean: {np.mean(error_ms):.3f} ms")
print(f"Median: {np.median(error_ms):.3f} ms")
print(f"Standard deviation: {np.std(error_ms):.3f} ms")

print("\nABSOLUTE TIMING ERROR")
print(f"Mean: {np.mean(absolute_error_ms):.3f} ms")
print(f"Median: {np.median(absolute_error_ms):.3f} ms")
print(f"90th percentile: {np.percentile(absolute_error_ms, 90):.3f} ms")
print(f"95th percentile: {np.percentile(absolute_error_ms, 95):.3f} ms")
print(f"Maximum: {np.max(absolute_error_ms):.3f} ms")

print("\nERROR COUNTS")
print("Detections after reference:", int(np.sum(error_samples > 0)))
print("Detections before reference:", int(np.sum(error_samples < 0)))
print("Exact sample matches:", int(np.sum(error_samples == 0)))

print("\nFirst 20 signed errors (ms):")
print(error_ms[:20])

# ============================================================
# 5. SAVE NEW MATCHED PAIRS AND ERROR DATA
# ============================================================

output_dir = Path(__file__).resolve().parent

np.save(
    output_dir / "a01_detector4_matched_pairs_no_minus4.npy",
    matched
)

error_data = np.column_stack([
    reference_matched / fs,
    detected_matched / fs,
    error_samples,
    error_ms
])

np.savetxt(
    output_dir / "a01_detector4_timing_errors_no_minus4.csv",
    error_data,
    delimiter=",",
    header="reference_time_s,detected_time_s,error_samples,error_ms",
    comments="",
    fmt="%.5f"
)

print("\nSaved modified matched pairs and timing-error CSV in:")
print(output_dir)

# ============================================================
# 6. FILTER ECG FOR VISUAL INSPECTION
# ============================================================

sos = butter(
    4, [0.5, 40.0],
    btype="bandpass",
    fs=fs,
    output="sos"
)
filtered_ecg = sosfiltfilt(sos, ecg)

# ============================================================
# 7. PLOT TIMING-ERROR DISTRIBUTION AND TREND
# ============================================================

reference_times = reference_matched / fs

fig, axes = plt.subplots(2, 1, figsize=(13, 9))

axes[0].hist(
    error_ms,
    bins=np.arange(-55, 61, 10),
    edgecolor="black"
)
axes[0].axvline(0, linestyle="--", label="Zero error")
axes[0].axvline(
    np.median(error_ms),
    linestyle="--",
    label=f"Median = {np.median(error_ms):.1f} ms"
)
axes[0].set_xlabel("Signed timing error (ms)")
axes[0].set_ylabel("Number of beats")
axes[0].set_title("Detector 4 vs modified sqrs125: timing errors")
axes[0].legend()
axes[0].grid(True)

axes[1].scatter(
    reference_times / 3600,
    error_ms,
    s=3,
    alpha=0.5
)
axes[1].axhline(0, linestyle="--")
axes[1].axhline(
    np.median(error_ms),
    linestyle="--",
    label=f"Median = {np.median(error_ms):.1f} ms"
)
axes[1].set_xlabel("Recording time (hours)")
axes[1].set_ylabel("Signed timing error (ms)")
axes[1].set_title("Timing error across the overnight recording")
axes[1].legend()
axes[1].grid(True)

plt.tight_layout()
plt.show()

# ============================================================
# 8. PLOT REPRESENTATIVE BEATS
# ============================================================

example_indices = np.unique(
    np.linspace(
        0, len(matched) - 1,
        min(6, len(matched)),
        dtype=int
    )
)

fig, axes = plt.subplots(
    len(example_indices), 1,
    figsize=(12, 2.8 * len(example_indices)),
    squeeze=False
)

half_window = int(round(0.30 * fs))

for ax, idx in zip(axes[:, 0], example_indices):
    ref = int(reference_matched[idx])
    det = int(detected_matched[idx])

    start = max(0, min(ref, det) - half_window)
    end = min(len(filtered_ecg), max(ref, det) + half_window + 1)

    sample_indices = np.arange(start, end)
    times = (sample_indices - ref) / fs

    ax.plot(times, filtered_ecg[start:end], label="Filtered ECG")
    ax.axvline(0, linestyle="--", label="Modified reference")
    ax.axvline(
        (det - ref) / fs,
        linestyle=":",
        label="Detector 4 peak"
    )
    ax.set_xlabel("Time relative to reference (s)")
    ax.set_ylabel("Amplitude")
    ax.set_title(
        f"Beat {idx + 1}: reference={ref}, detected={det}, "
        f"error={error_ms[idx]:+.1f} ms"
    )
    ax.legend(loc="upper right")
    ax.grid(True)

plt.tight_layout()
plt.show()

print("\nTiming analysis complete.")
